  })).campaign;

  // Schedule for 1 second in future
  const schedTime = (await db.query("select to_char((clock_timestamp() + interval '1 second') at time zone 'UTC', 'YYYY-MM-DD\"T\"HH24:MI:SS.US\"Z\"') as t")).rows[0].t;

