    await asUser(adminId, 'authenticated', async () => {
      await db.exec(`
        select public.admin_schedule_notification_campaign(
          '${reqNewPast}', '${draft.id}', ${first.campaign.revision}, '${schedTime}'::timestamptz, 'New past'
